local TimerModule = CS.Engine.Modules.TimerModule
local KTool = CS.Engine.Lib.KTool

local PLAYER_TIME = 3

--- from: Assets/BundleResources/Prefabs/LoginQueueWaitDialog.prefab
---@class LoginQueueWaitDialog
---@field Env                           	LoginQueueWaitDialog
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field TxtNumber                     	TMPro.TextMeshProUGUI
---@field TxtWaitNumber                 	UnityEngine.UI.Text
local LoginQueueWaitDialog = Class('LoginQueueWaitDialog')

function LoginQueueWaitDialog:__init()
    TimerModule.Instance:AddTimer(Constants.TimerName.LoginQueueWaitDialogTimer, 0, 10, Bind(self, self.RefreshQueueInfo))
end

function LoginQueueWaitDialog:__delete()
    TimerModule.Instance:RemoveTimer(Constants.TimerName.LoginQueueWaitDialogTimer)
end

function LoginQueueWaitDialog:Awake()
end

function LoginQueueWaitDialog:Start()
end

function LoginQueueWaitDialog:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

-------------------------------------------- get/set
function LoginQueueWaitDialog:SetQueueNum(num)
    self.queueNum_ = checkInt(num)
end
function LoginQueueWaitDialog:GetQueueNum()
    return checkInt(self.queueNum_)
end

function LoginQueueWaitDialog:SetPlayerNum(num)
    self.playerNum_ = checkInt(num)
    CfUtils.FillText(self.TxtNumber, self:GetPlayerNum())

    local time = self:GetPlayerNum() * PLAYER_TIME
    local desc = ""
    if time <= 60 then
        desc = localize("小于1分钟")
    elseif time >= 60 * 60 then
        desc = localize("大于60分钟")
    else
        desc = string.format(localize("%s分钟"), math.ceil(time / 60))
    end
    CfUtils.FillText(self.TxtWaitNumber, desc)

    if self:GetPlayerNum() <= 0 then
        KTool.SafeDelete(self.controller.gameObject, true)
        if self:GetCallBack() then
            self:GetCallBack()()
        end
    end
end
function LoginQueueWaitDialog:GetPlayerNum()
    return checkInt(self.playerNum_)
end


function LoginQueueWaitDialog:SetCallBack(handler)
    self.closeCB_ = handler
end
function LoginQueueWaitDialog:GetCallBack()
    return self.closeCB_
end

-------------------------------------------- public

function LoginQueueWaitDialog:RefreshQueueInfo()
    GameUtils.Request(Interfaces.UserCheckQueue, {queueNum = self:GetQueueNum()}, function(request, response)
        if tonumber(response.errCode) == 0 then
            self:SetPlayerNum(response.data.result)
        end
    end)
end

return LoginQueueWaitDialog
 
 